import org.jsoup.nodes.*;
import org.jsoup.parser.*;
import org.junit.Test;
import java.io.StringReader;
import java.util.List;

import static org.junit.Assert.*;

public class XmlTreeBuilderTest {

	@Test
	public void defaultSettingsTest() {
		XmlTreeBuilder builder = new XmlTreeBuilder();
		assertNotNull(builder.defaultSettings());
	}

	@Test
	public void newInstanceTest() {
		XmlTreeBuilder builder = new XmlTreeBuilder();
		XmlTreeBuilder instance = builder.newInstance();
		assertNotNull(instance);
		assertNotSame(builder, instance);
	}

	@Test
	public void parseStringBaseUriTest() {
		XmlTreeBuilder builder = new XmlTreeBuilder();
		Document doc = builder.parse("<root>", "http://test/");
		assertNotNull(doc);
		assertEquals(1, doc.childNodeSize());
		assertEquals("root", doc.childNode(0).nodeName());
	}

	@Test
	public void parseReaderBaseUriTest() {
		StringReader reader = new StringReader("<root>");
		XmlTreeBuilder builder = new XmlTreeBuilder();
		Document doc = builder.parse(reader, "http://test/");
		assertNotNull(doc);
		assertEquals(1, doc.childNodeSize());
		assertEquals("root", doc.childNode(0).nodeName());
	}

	@Test
	public void initialiseParseTest() {
		XmlTreeBuilder builder = new XmlTreeBuilder();
		StringReader reader = new StringReader("<root>");
		Parser parser = Parser.xmlParser();
		builder.initialiseParse(reader, "", parser);
		String baseUri = builder.getBaseUri();
		reader.close();
		assertNotNull(baseUri);
	}

	@Test
	public void insertCharacterTokenTest() {
		XmlTreeBuilder builder = new XmlTreeBuilder();
		Token.Character characterToken = new Token.Character();
		characterToken.data("test");
		builder.insert(characterToken);
		List<Node> childNodes = builder.getStack();
		assertEquals(childNodes.get(0).childNode(0).nodeName(), "#text");
		assertEquals(((TextNode) childNodes.get(0).childNode(0)).text(), "test");
	}

